const staticData = $getWorkflowStaticData('global');

if (!staticData.lastCheckIso) {
  // First run: only pick up orders from the last 30 minutes
  staticData.lastCheckIso = new Date(Date.now() - 30 * 60 * 1000).toISOString();
}

if (!Array.isArray(staticData.sentOrderIds)) {
  staticData.sentOrderIds = [];
}

return [
  {
    json: {
      lastCheckIso: staticData.lastCheckIso,
      sentOrderIds: staticData.sentOrderIds,
    },
  },
];

const staticData = $getWorkflowStaticData('global');
const sentIds = new Set(staticData.sentOrderIds || []);
const incoming = $input.all().map((item) => item.json);

// HTTP node may return one item per order, or a single array item
let orders = [];
if (incoming.length === 1 && Array.isArray(incoming[0])) {
  orders = incoming[0];
} else if (incoming.length === 1 && Array.isArray(incoming[0].body)) {
  orders = incoming[0].body;
} else {
  orders = incoming;
}

const freshOrders = orders.filter((order) => order?.id && !sentIds.has(order.id));

if (!freshOrders.length) {
  return [];
}

return freshOrders.map((order) => ({ json: order }));

const order = $input.item.json;
const shipping = order.shipping_address || {};
const currency = order.currency || 'KES';

const customerName =
  order.customer?.full_name ||
  shipping.fullName ||
  shipping.firstName ||
  'Guest';

const customerEmail =
  order.customer?.email ||
  shipping.email ||
  'N/A';

const customerPhone = shipping.phone || 'N/A';

const items = (order.order_items || [])
  .map((item) => {
    const name = item.product?.name || item.variation_name || 'Product';
    const options = [
      item.selected_size,
      item.selected_color,
      item.selected_weight,
      item.selected_dimension,
    ]
      .filter(Boolean)
      .join(', ');

    const lineTotal = Number(item.price || 0) * Number(item.quantity || 1);
    return `• ${name}${options ? ` (${options})` : ''} x${item.quantity} — ${currency} ${lineTotal.toLocaleString()}`;
  })
  .join('\n');

const shortId = String(order.id).slice(0, 8).toUpperCase();
const createdAt = new Date(order.created_at).toLocaleString('en-KE', {
  timeZone: 'Africa/Nairobi',
  dateStyle: 'medium',
  timeStyle: 'short',
});

const message = [
  '🛍️ *New NAKMA Store Order*',
  '',
  `*Order:* #${shortId}`,
  `*Status:* ${order.status || 'Pending'}`,
  `*Payment:* ${order.payment_status || 'Pending'} (${order.payment_method || 'N/A'})`,
  `*Total:* ${currency} ${Number(order.total_amount || 0).toLocaleString()}`,
  '',
  '*Customer*',
  customerName,
  customerEmail,
  customerPhone,
  '',
  '*Delivery*',
  shipping.deliveryLocation || shipping.line1 || 'Not specified',
  shipping.method ? `Method: ${shipping.method}` : '',
  shipping.country ? `Country: ${shipping.country}` : '',
  '',
  '*Items*',
  items || 'No line items found',
  '',
  `_Placed: ${createdAt}_`,
].filter(Boolean).join('\n');

return {
  json: {
    orderId: order.id,
    createdAt: order.created_at,
    message,
    recipientPhone: '254722714693',
  },
};

const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.sentOrderIds)) {
  staticData.sentOrderIds = [];
}

const processed = $('Format WhatsApp Message').all();

for (const item of processed) {
  const orderId = item.json.orderId;
  if (orderId && !staticData.sentOrderIds.includes(orderId)) {
    staticData.sentOrderIds.push(orderId);
  }
}

// Keep static list from growing forever
if (staticData.sentOrderIds.length > 500) {
  staticData.sentOrderIds = staticData.sentOrderIds.slice(-500);
}

const latestCreatedAt = processed
  .map((item) => item.json.createdAt)
  .filter(Boolean)
  .sort()
  .pop();

if (latestCreatedAt) {
  staticData.lastCheckIso = latestCreatedAt;
} else {
  staticData.lastCheckIso = new Date().toISOString();
}

return [
  {
    json: {
      sentCount: processed.length,
      lastCheckIso: staticData.lastCheckIso,
    },
  },
];
